<tbody><?php $totSales = 0; $totCollect = 0; $totPaid = 0; $totBonus = 0; $totBonusCost = 0; $totPayable = 0; foreach ($rows as $r): $totSales += (float)$r['sales']; $totCollect += (float)$r['collected']; $totPaid += (float)$r['issued_paid']; $totBonus += (float)$r['issued_bonus']; $totBonusCost += (float)$r['issued_bonus_cost']; $totPayable += (float)$r['issued_payable']; ?>
<tr><td><strong><?= e($r['name']) ?></strong><br><span class="muted"><?= e($r['area'] ?? '') ?></span></td><td><?= e($r['warehouse'] ?? '—') ?></td><td class="num"><?= qty($r['current_stock']) ?></td><td class="num"><?= number_format($r['current_value'], 2) ?></td><td class="num"><?= qty($r['issued_paid']) ?></td><td class="num"><?= qty($r['issued_bonus']) ?></td><td class="num"><?= money($r['issued_payable'], false) ?></td><td class="num"><?= money($r['issued_bonus_cost'], false) ?></td><td class="num"><?= (int)$r['invoices'] ?></td><td class="num"><?= money($r['sales'], false) ?></td><td class="num"><?= money($r['collected'], false) ?></td><td class="num"><?= qty($r['commission_percent']) ?></td></tr>
<?php endforeach; ?></tbody>
<tfoot><tr><th colspan="4"><?= __('TOTALS') ?></th><th class="num"><?= qty($totPaid) ?></th><th class="num"><?= qty($totBonus) ?></th><th class="num"><?= money($totPayable, false) ?></th><th class="num"><?= money($totBonusCost, false) ?></th><th></th><th class="num"><?= money($totSales, false) ?></th><th class="num"><?= money($totCollect, false) ?></th><th></th></tr></tfoot></table></div>
